CREATE TABLE app_user (id VARCHAR(36) PRIMARY KEY, provider VARCHAR(24) NOT NULL, subject VARCHAR(120) NOT NULL, name VARCHAR(40) NOT NULL, UNIQUE(provider, subject));
CREATE TABLE household (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, owner_id VARCHAR(36) NOT NULL REFERENCES app_user(id), planned_people INTEGER NOT NULL CHECK(planned_people >= 1), revision BIGINT NOT NULL);
CREATE TABLE membership (id VARCHAR(36) PRIMARY KEY, household_id VARCHAR(36) NOT NULL REFERENCES household(id), user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), name VARCHAR(40) NOT NULL, appearance VARCHAR(24) NOT NULL, role VARCHAR(16) NOT NULL, place VARCHAR(16) NOT NULL, mood VARCHAR(80) NOT NULL, food VARCHAR(80) NOT NULL, thought VARCHAR(200) NOT NULL, status_expires_at TIMESTAMP(6), status_updated_at TIMESTAMP(6), x DOUBLE NOT NULL, y DOUBLE NOT NULL, action VARCHAR(24) NOT NULL, avatar_updated_at TIMESTAMP(6), active BOOLEAN NOT NULL, UNIQUE(household_id,user_id));
CREATE TABLE pet (id VARCHAR(36) PRIMARY KEY, household_id VARCHAR(36) NOT NULL REFERENCES household(id), name VARCHAR(40) NOT NULL, kind VARCHAR(24) NOT NULL, appearance VARCHAR(24) NOT NULL);
CREATE TABLE invitation (id VARCHAR(36) PRIMARY KEY, household_id VARCHAR(36) NOT NULL REFERENCES household(id), token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP(6), cancelled BOOLEAN NOT NULL, accepted_by VARCHAR(36) REFERENCES app_user(id), accepted_at TIMESTAMP(6));
CREATE TABLE pantry_item (id VARCHAR(36) PRIMARY KEY, household_id VARCHAR(36) NOT NULL REFERENCES household(id), name VARCHAR(80) NOT NULL, location VARCHAR(40) NOT NULL, quantity DOUBLE NOT NULL CHECK(quantity >= 0), unit VARCHAR(16) NOT NULL, expires_on DATE, version BIGINT NOT NULL, updated_at TIMESTAMP(6));
CREATE TABLE pantry_change (id VARCHAR(36) PRIMARY KEY, household_id VARCHAR(36) NOT NULL REFERENCES household(id), item_id VARCHAR(36) NOT NULL REFERENCES pantry_item(id), author_member_id VARCHAR(36) NOT NULL REFERENCES membership(id), previous_quantity DOUBLE NOT NULL, quantity DOUBLE NOT NULL, created_at TIMESTAMP(6));
CREATE TABLE life_event (id VARCHAR(36) PRIMARY KEY, household_id VARCHAR(36) NOT NULL REFERENCES household(id), author_member_id VARCHAR(36) NOT NULL REFERENCES membership(id), author_name VARCHAR(40) NOT NULL, request_id VARCHAR(80) NOT NULL, type VARCHAR(30) NOT NULL, message VARCHAR(300) NOT NULL, created_at TIMESTAMP(6), UNIQUE(household_id,author_member_id,request_id));
CREATE INDEX member_user_idx ON membership(user_id);
CREATE INDEX event_history_idx ON life_event(household_id,created_at);
CREATE INDEX pantry_household_idx ON pantry_item(household_id);
